static int tls_ctx_connect_once(tls_ctx_t* ctx, const char* host, const char* port)
{
    int ret;

    mbedtls_ssl_init(&ctx->ssl);
    mbedtls_ssl_config_init(&ctx->cfg);
    mbedtls_net_init(&ctx->net);
    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);

    /* Seed RNG directly with our robust function */
    const char* pers = "vela_tls";
    if ((ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, simple_entropy_func, NULL,
             (const unsigned char*)pers,
             strlen(pers)))
        != 0) {
        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=0x%x\n", TAG, -ret);
        return VELA_TLS_ERR_HANDSHAKE;
    }

    /* Check system time — crucial for TLS certificate validation. */
    time_t now = time(NULL);
    syslog(LOG_DEBUG, "[%s] Handshake start: Host=%s, UNIX=%ld\n", TAG, host, (long)now);

    if (now < 1704067200) { /* Jan 1 2024 */
        syslog(LOG_WARNING, "[%s] Clock too old, forcing to 2026\n", TAG);
        struct timespec ts = { .tv_sec = 1772275200, .tv_nsec = 0 };
        clock_settime(CLOCK_REALTIME, &ts);
    }

    /* TCP connect — use HTTP CONNECT proxy if configured */
#ifdef CONFIG_AI_AGENT_NET_RPMSG
    {
        int res_ret = network_acquire_resource(network_get_connect_timeout() * 1000);
        if (res_ret != 0) {
            syslog(LOG_ERR, "[%s] Resource acquire failed: %d\n", TAG, res_ret);
            return VELA_TLS_ERR_CONNECT;
        }
    }
#endif

    if (http_proxy_is_enabled()) {
        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
        if (tunnel_fd < 0) {
            syslog(LOG_ERR, "[%s] proxy tunnel to %s:%s failed\n",
                TAG, host, port);
            return VELA_TLS_ERR_CONNECT;
        }
        ctx->net.fd = tunnel_fd;
        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
            TAG, tunnel_fd, host, port);
    } else {
        /* ★ connect() 偶发失败必须自己重试，不能往上抛
         *
         * 2026-10-23 真机抓包：同一秒内
         *   Handshake start -> net_connect ret=0x44（=MBEDTLS_ERR_NET_CONNECT_FAILED，
         *   即 connect() 失败，123ms 就返回，不是超时）-> 整轮报"网络好像不太稳"；
         *   紧接着下一次 Handshake start -> Handshake OK。
         * 也就是说这是一次**瞬时**的 connect 失败（对端/RNDIS NAT 抖一下），
         * 但上层一次失败就直接给用户弹兜底文案，观感就是"非常不稳定"。
         *
         * 重试放在这一层的好处：LLM / ASR / TTS 三条链路都走 tls_ctx_connect，
         * 一起受益。每次失败 mbedtls_net_connect 都会 close 掉自己建的 socket，
         * 不会漏 fd；这里再显式 free+init 一次，保证重试是个干净的 ctx。
         */
        for (int attempt = 0;; attempt++) {
            ret = mbedtls_net_connect(&ctx->net, host, port,
                MBEDTLS_NET_PROTO_TCP);
            if (ret == 0) {
                break;
            }

            syslog(LOG_ERR,
                "[%s] net_connect %s:%s ret=0x%x errno=%d (第 %d/%d 次)\n",
                TAG, host, port, -ret, errno, attempt + 1,
                TLS_CONNECT_ATTEMPTS);

            /* ★ 0x42 = MBEDTLS_ERR_NET_SOCKET_FAILED = socket() 自己失败
             * （不是 connect、不是 DNS）。errno=12(ENOMEM) 来自
             * net/tcp/tcp_conn.c 的 tcp_alloc()：mempool 在 nalloc >= maxalloc
             * 时**先于空闲队列**就返回 NULL。到这一步"谁占着连接不放"光看
             * 这一行是猜不出来的，所以顺手把连接池快照打出来（只在最后一次
             * 重试打，一轮 3 条链路最多 3 行，且只在故障时出现）。
             * 判据见 nuttx/include/nuttx/net/tcp.h 的 tcp_conn_probe 注释：
             * TW 独大 = 收尾没跑完；EST/SNT 独大 = fd 真漏了。 */
            if (ret == MBEDTLS_ERR_NET_SOCKET_FAILED &&
                attempt + 1 >= TLS_CONNECT_ATTEMPTS)
              {
                struct tcp_conn_probe_s tp;
                char st[96];
                char pr[96];
                int  i;
                int  n;

                tcp_conn_probe(&tp);

                snprintf(st, sizeof(st),
                         "D%d AR%d SNT%d EST%d F1:%d F2:%d CW:%d CL:%d TW:%d LA:%d",
                         tp.nstate[TCP_CLOSED], tp.nstate[TCP_ALLOCATED],
                         tp.nstate[TCP_SYN_SENT], tp.nstate[TCP_ESTABLISHED],
                         tp.nstate[TCP_FIN_WAIT_1], tp.nstate[TCP_FIN_WAIT_2],
                         tp.nstate[TCP_CLOSE_WAIT], tp.nstate[TCP_CLOSING],
                         tp.nstate[TCP_TIME_WAIT], tp.nstate[TCP_LAST_ACK]);

                pr[0] = '\0';
                n = 0;
                for (i = 0; i < tp.npeer && n < (int)sizeof(pr) - 1; i++)
                  {
                    int w = snprintf(pr + n, sizeof(pr) - n, "%s%u:%d",
                                     (n > 0) ? " " : "",
                                     (unsigned)ntohs(tp.peer[i].rport),
                                     tp.peer[i].count);
                    if (w < 0 || w >= (int)sizeof(pr) - n)
                      {
                        break;
                      }
                    n += w;
                  }

                syslog(LOG_ERR, "[TCP] pool=%d/%d act=%d st[%s] peers[%s]\n",
                       tp.used, tp.cap, tp.nactive, st,
                       (pr[0] != '\0') ? pr : "-");
              }

            mbedtls_net_free(&ctx->net);
            mbedtls_net_init(&ctx->net);

            if (attempt + 1 >= TLS_CONNECT_ATTEMPTS) {
                return VELA_TLS_ERR_CONNECT;
            }
            usleep(TLS_CONNECT_RETRY_DELAY_US * (attempt + 1));
        }
    }

    /* Force blocking mode and set socket-level read timeout.
     * This avoids using select()/poll() inside mbedtls_net_recv_timeout
     * which returns MBEDTLS_ERR_NET_POLL_FAILED (-0x0047) on NuttX/QEMU.
     * Timeout is configured via AGENT_LLM_SOCKET_TIMEOUT_SEC in
     * agent_config.h.  LLM APIs (especially kimi with thinking mode)
     * can take over 60s for long responses. */
    mbedtls_net_set_block(&ctx->net);
    if (ctx->net.fd >= 0) {
#ifdef CONFIG_AI_AGENT_NET_RPMSG
        int read_timeout_sec = network_get_read_timeout();
        struct timeval tv = { .tv_sec = read_timeout_sec, .tv_usec = 0 };
#else
        struct timeval tv = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
            .tv_usec = 0 };
#endif
        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

        /* 发送也要有超时（2026-09-14 补）：原来只在 CONFIG_AI_AGENT_NET_RPMSG
         * 下才设 SO_SNDTIMEO，我们这版没开 → TLS 的 write 没有上限。对端失联时
         * 一次 send 会一直等 TCP 重传（分钟级），表现是"识别/AI 回复卡在
         * 处理中、连握手日志都没有"。30s 对 1.5MB 的 TTS/ASR 请求体也绰绰有余
         * （USB RNDIS 链路上传 MB 级只要一两秒），超时就让它报错走失败分支。 */

        {
            struct timeval stv = { .tv_sec = 30, .tv_usec = 0 };
            setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &stv, sizeof(stv));
        }

#ifdef CONFIG_AI_AGENT_NET_RPMSG
        {
            int timeout_sec = network_get_connect_timeout();
            struct timeval ctv = { .tv_sec = timeout_sec, .tv_usec = 0 };
            setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));
        }
#endif
    }

