        return SM_STATE_CARE_REMIND;

      case SM_EVENT_ALARM_DETECTED:
        /* 异常声音检测到 */

        return SM_STATE_ALARM;

      case SM_EVENT_SLEEP:
        /* 保持待机状态 */

        return SM_STATE_IDLE;

