  sm_register_state(ctx, SM_STATE_CARE_REMIND,
                    sm_care_remind_enter, sm_care_remind_exit,
                    sm_care_remind_transition);

  sm_register_state(ctx, SM_STATE_ALARM,
                    sm_alarm_enter, sm_alarm_exit, sm_alarm_transition);

