       * 上层的 -ENODEV 分支会把这一支归到"自己断粮"，走 STOP + close。
       * -ENODEV 同时也是 diag 快照 lres 那一栏里一眼可读的证据。 */

      syslog(LOG_WARNING, "AUDIO: read 时设备没在跑（len=%zu running=%d）→ "
             "返回 -ENODEV，请上层按'设备没在跑'收（不是被抢走）\n",
             buflen, (int)priv->running);
      return -ENODEV;

    return -ENODEV;
  }

