    m->confirmed = confirmed;
    snprintf(m->src, sizeof(m->src), "%s", (src != NULL) ? src : "-");

    if (ui_async_call(ui_apply_ask_answer, m) != LV_RESULT_OK) {
        printf("[Ask] 回答投递失败（内存紧），丢弃一次\n");
        free(m);
    }
}

